// Step-by-step walkthrough of one real forward pass of the nano LM.
// Data comes from web/trace_data.js (generated by training/export_trace.py).
(() => {
  "use strict";

  const T = window.TRACE;
  const $ = (id) => document.getElementById(id);
  const root = $("walkthrough");
  if (!root) return;
  if (!T) {
    $("wt-title").textContent = "Trace data not found";
    $("wt-plain").textContent =
      "Run `.venv/bin/python training/export_trace.py` to generate web/trace_data.js, then reload.";
    return;
  }

  const cfg = T.config;
  const toks = T.prompt.map((p) => p.token);
  const last = toks.length - 1;
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const fmt = (n) => n.toLocaleString("en-US");
  const pct = (p) => (p >= 0.9995 ? "≈100%" : p < 0.0005 ? "<0.1%" : (p * 100).toFixed(p < 0.1 ? 2 : 1) + "%");

  // ---------- drawing helpers ----------
  function robustScale(values) {
    const abs = values.map(Math.abs).sort((a, b) => a - b);
    return abs[Math.floor(abs.length * 0.98)] || 1;
  }
  function rgb(v, scale) {
    const x = Math.max(-1, Math.min(1, v / scale));
    const base = [15, 23, 42];
    const hi = x >= 0 ? [251, 146, 60] : [56, 189, 248];
    const t = Math.abs(x);
    return base.map((b, i) => Math.round(b + (hi[i] - b) * t));
  }
  function matrixCanvas(rows, scale, cssHeight) {
    const h = rows.length, w = rows[0].length;
    const c = document.createElement("canvas");
    c.width = w; c.height = h;
    c.className = "wt-matrix";
    if (cssHeight) c.style.height = cssHeight;
    const ctx = c.getContext("2d");
    const img = ctx.createImageData(w, h);
    const s = scale || robustScale(rows.flat());
    rows.forEach((row, y) => row.forEach((v, x) => {
      const [r, g, b] = rgb(v, s);
      const o = (y * w + x) * 4;
      img.data[o] = r; img.data[o + 1] = g; img.data[o + 2] = b; img.data[o + 3] = 255;
    }));
    ctx.putImageData(img, 0, 0);
    return c;
  }
  const strip = (values, scale, h = "16px") => matrixCanvas([values], scale, h);

  function el(tag, cls, text) {
    const e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text !== undefined) e.textContent = text;
    return e;
  }
  function labeledStrip(label, values, scale, note) {
    const row = el("div", "wt-strip-row");
    row.append(el("span", "wt-strip-label", label), strip(values, scale));
    if (note) row.append(el("span", "wt-strip-note", note));
    return row;
  }
  function bars(items, { highlight, showLogit } = {}) {
    const wrap = el("div", "wt-bars");
    const max = Math.max(...items.map((i) => i.p), 1e-9);
    items.forEach((item) => {
      const row = el("div", "wt-bar-row" + (highlight && highlight(item) ? " is-hot" : ""));
      row.append(el("span", "wt-bar-label", item.token));
      const track = el("span", "wt-bar-track");
      const fill = el("span", "wt-bar-fill");
      fill.style.width = Math.max(0.6, (item.p / max) * 100) + "%";
      track.append(fill);
      row.append(track, el("span", "wt-bar-val", pct(item.p) + (showLogit ? `  (score ${item.logit})` : "")));
      wrap.append(row);
    });
    return wrap;
  }
  function legend() {
    const l = el("div", "wt-legend");
    l.innerHTML = '<span class="sw neg"></span>negative <span class="sw zero"></span>near zero <span class="sw pos"></span>positive';
    return l;
  }
  function histogramCanvas(h) {
    const c = document.createElement("canvas");
    const dpr = window.devicePixelRatio || 1;
    const W = 520, H = 130;
    c.width = W * dpr; c.height = H * dpr;
    c.className = "wt-hist";
    const ctx = c.getContext("2d");
    ctx.scale(dpr, dpr);
    const max = Math.max(...h.counts);
    const bw = W / h.counts.length;
    h.counts.forEach((n, i) => {
      const bh = (n / max) * (H - 18);
      const mid = h.min + ((i + 0.5) / h.counts.length) * (h.max - h.min);
      const [r, g, b] = rgb(mid, Math.max(Math.abs(h.min), Math.abs(h.max)));
      ctx.fillStyle = `rgb(${Math.max(r, 70)},${Math.max(g, 80)},${Math.max(b, 110)})`;
      ctx.fillRect(i * bw + 1, H - 14 - bh, bw - 2, bh);
    });
    ctx.fillStyle = "#94a3b8";
    ctx.font = "11px JetBrains Mono, monospace";
    ctx.fillText(h.min.toFixed(2), 2, H - 2);
    const mx = h.max.toFixed(2);
    ctx.fillText(mx, W - ctx.measureText(mx).width - 2, H - 2);
    ctx.fillText("0", W * (-h.min / (h.max - h.min)) - 3, H - 2);
    return c;
  }

  // ---------- residual stream map (left panel) ----------
  const stageNames = ["Embedding", ...Array.from({ length: cfg.layers }, (_, i) => `Layer ${i + 1}`)];
  const mapScale = robustScale(T.trace.residual.flat(2));
  const map = $("wt-map");
  const mapRows = [];
  (function buildMap() {
    const head = el("div", "wt-map-row wt-map-head");
    head.append(el("span", "wt-map-label", ""));
    toks.forEach((t, i) => {
      const clean = t.replace(/^<|>$/g, "");
      const short = clean
        .replace("CHAR=", "")
        .replace("MODE=", "")
        .replace("PLACE=", "")
        .replace("THEME=", "");
      const tokSpan = el("span", "wt-map-tok" + (i === last ? " is-last" : ""), short);
      tokSpan.title = `Token ${i}: ${t}`;
      head.append(tokSpan);
    });
    map.append(head);
    T.trace.residual.forEach((stage, s) => {
      const row = el("div", "wt-map-row");
      row.append(el("span", "wt-map-label", stageNames[s]));
      stage.forEach((vec, i) => {
        const cell = strip(vec, mapScale, "14px");
        if (i === last) cell.classList.add("is-last");
        cell.title = `${stageNames[s]} · Token ${i} (${toks[i]})`;
        row.append(cell);
      });
      map.append(row);
      mapRows.push(row);
    });
  })();
  function highlightMap(stage) {
    mapRows.forEach((r, i) => {
      r.classList.toggle("is-active", i === stage);
      r.classList.toggle("is-done", stage !== null && i < stage);
    });
  }

  // ---------- steps ----------
  const steps = [];
  const chapter = (name) => ({ name });

  // 0. Weights
  steps.push({
    chapter: "Weights", stage: null,
    kicker: "Step 0 · What the model has learned",
    title: `The model's memory: ${fmt(T.weights.total_params)} numbers`,
    plain: `Before any story is written, the model is just a big pile of numbers called weights. Training adjusted each one, a tiny bit at a time, until the model got good at guessing the next word of the training stories. Nothing else is stored: no story text and no list of rules, just these numbers. Pick a weight tensor below to see real values from the checkpoint.`,
    numbers: `Checkpoint: ${T.checkpoint} · ${T.weights.tensors.length} tensors · stored as 32-bit floats on the host (INT4 packing for the device is planned).`,
    render(v) {
      const names = Object.keys(T.weights.hist);
      const picker = el("div", "wt-pills");
      const body = el("div", "wt-weight-body");
      const describe = {
        "embed.weight": "Word table: one row of 128 numbers per token (752 rows). Also reused at the very end to score every possible next word.",
        "blocks.0.attn.qkv.weight": "Layer 1 attention: turns each token's vector into a query, a key and a value.",
        "blocks.0.attn.proj.weight": "Layer 1 attention output: mixes the 8 heads' results back into one vector.",
        "blocks.0.up.weight": "Layer 1 feed-forward 'up' matrix: 128 → 512 features.",
        "blocks.0.down.weight": "Layer 1 feed-forward 'down' matrix: 512 → 128.",
        "blocks.0.attn.norm.weight": "Layer 1 RMSNorm gains: one scale factor per dimension.",
      };
      const show = (name) => {
        [...picker.children].forEach((b) => b.classList.toggle("is-on", b.dataset.name === name));
        body.replaceChildren();
        const st = T.weights.tensors.find((t) => t.name === name);
        body.append(el("p", "wt-small", describe[name] || ""));
        body.append(el("div", "wt-mono",
          `shape [${st.shape.join(" × ")}] · ${fmt(st.params)} numbers · min ${st.min} · max ${st.max} · mean ${st.mean} · std ${st.std}`));
        const hWrap = el("div", "wt-figure");
        hWrap.append(el("div", "wt-fig-cap", "How the values are spread (histogram)"), histogramCanvas(T.weights.hist[name]));
        body.append(hWrap);
        if (T.weights.crops[name]) {
          const cWrap = el("div", "wt-figure");
          cWrap.append(el("div", "wt-fig-cap", "A 24 × 32 corner of the actual matrix (each square is one weight)"),
            matrixCanvas(T.weights.crops[name], null, "auto"), legend());
          if (name === "embed.weight") cWrap.append(el("div", "wt-small", "Rows shown: " + T.weights.crop_rows_embed.join("  ")));
          body.append(cWrap);
        } else if (name.endsWith("norm.weight")) {
          const cWrap = el("div", "wt-figure");
          cWrap.append(el("div", "wt-fig-cap", "All 128 gains"), strip(T.weights.norm_l0, null, "22px"));
          body.append(cWrap);
        }
      };
      names.forEach((n) => {
        const b = el("button", "wt-pill", n.replace("blocks.0.", "layer1.").replace(".weight", ""));
        b.type = "button"; b.dataset.name = n;
        b.addEventListener("click", () => show(n));
        picker.append(b);
      });
      const groups = el("div", "wt-groups");
      const per = T.weights.tensors.filter((t) => t.name.startsWith("blocks.0.")).reduce((a, t) => a + t.params, 0);
      [["Word table (shared in/out)", cfg.vocab * cfg.d_model],
       [`${cfg.layers} layers × ${fmt(per)}`, per * cfg.layers],
       ["Final norm", cfg.d_model]].forEach(([k, n]) => {
        const g = el("div", "wt-group");
        g.append(el("span", "", k), el("strong", "", fmt(n)));
        groups.append(g);
      });
      v.append(groups, picker, body);
      show(names[0]);
    },
  });

  // 1. Prompt
  steps.push({
    chapter: "Prompt", stage: null,
    kicker: "Step 1 · The starting prompt",
    title: "The child's choices become 6 numbers",
    plain: `The model can't read. It only sees token ids, which are numbers. The picker choices (Bluey, bedtime, backyard, help) each map to one special token. <BOS> means "a new story starts here", and <LINE> means "now write the first line". The model's only job is to answer one question: which token comes next?`,
    numbers: `Vocabulary: ${cfg.vocab} tokens (30 control tokens + 722 words). Context window: up to ${cfg.ctx} tokens.`,
    render(v) {
      const meaning = ["start of story", "character: Bluey", "mode: bedtime", "place: backyard", "theme: help", "start writing a line"];
      const row = el("div", "wt-prompt");
      T.prompt.forEach((p, i) => {
        const chip = el("div", "wt-token" + (i === last ? " is-last" : ""));
        chip.append(el("span", "wt-token-text", p.token), el("span", "wt-token-id", "id " + p.id), el("span", "wt-token-mean", meaning[i] || ""));
        row.append(chip);
      });
      const q = el("div", "wt-question");
      q.append(el("span", "", toks.join(" ")), el("span", "wt-qmark", " → ?"));
      v.append(row, q);
    },
  });

  // 2. Embedding
  steps.push({
    chapter: "Embed", stage: 0,
    kicker: "Step 2 · Look up each token",
    title: "Each id becomes a list of 128 numbers",
    plain: `Each id picks one row from the word table, a list of 128 numbers called a vector. Think of it as the token's starting "meaning", written as coordinates. Every colored strip below is one token. Orange cells are positive, blue cells are negative. These vectors now travel up through 8 layers. On the left, the map shows all 6 tokens moving through every layer.`,
    numbers: `Lookup: embed.weight[id] → 128 floats per token. ${toks.length} tokens × 128 = ${toks.length * 128} numbers enter layer 1.`,
    render(v) {
      const s = robustScale(T.trace.embed.flat());
      T.trace.embed.forEach((vec, i) => v.append(labeledStrip(toks[i], vec, s)));
      v.append(legend());
    },
  });

  // 3. Layers
  T.trace.layers.forEach((layer, li) => {
    const n = li + 1;
    const heads = layer.attn_weights; // [h][t][t]
    const lastRows = heads.map((h) => h[last]);
    const focus = lastRows.map((row, h) => {
      const m = Math.max(...row);
      return { h, m, tok: toks[row.indexOf(m)] };
    }).sort((a, b) => b.m - a.m);
    const top = focus[0];

    steps.push({
      chapter: `L${n}`, stage: n,
      kicker: `Layer ${n} of ${cfg.layers} · Part A: attention`,
      title: "Which earlier tokens should <LINE> listen to?",
      plain: `Attention lets each token collect information from the tokens before it. We follow the last token, <LINE>, because its vector is the one that will predict the next word. There are ${cfg.heads} attention heads, and each one decides independently how much to listen to each earlier token. Their weights always add up to 100%. In this layer, head ${top.h + 1} is the most focused: it puts ${pct(top.m)} of its attention on ${top.tok}.`,
      numbers: `For each head: score = (query · key) / √${cfg.head_dim}, then softmax over the ${toks.length} visible tokens. A token can't see tokens after it (causal mask). RoPE rotates queries and keys so position is built into the scores.`,
      render(v) {
        const picker = el("div", "wt-pills");
        const detail = el("div", "wt-attn-detail");
        const show = (h) => {
          [...picker.children].forEach((b, i) => b.classList.toggle("is-on", i === h));
          detail.replaceChildren();
          detail.append(el("div", "wt-fig-cap", `Head ${h + 1}: where <LINE> looks`),
            bars(lastRows[h].map((p, i) => ({ token: toks[i], p })), { highlight: (it) => it.p === Math.max(...lastRows[h]) }));
          const m = el("div", "wt-figure");
          m.append(el("div", "wt-fig-cap", `Head ${h + 1}, every token (rows look at columns; the top-right triangle is blocked)`));
          m.append(attnGrid(heads[h]));
          detail.append(m);
        };
        heads.forEach((_, h) => {
          const b = el("button", "wt-pill", `head ${h + 1}`);
          b.type = "button";
          b.addEventListener("click", () => show(h));
          picker.append(b);
        });
        v.append(picker, detail);
        show(top.h);
      },
    });

    steps.push({
      chapter: `L${n}`, stage: n,
      kicker: `Layer ${n} of ${cfg.layers} · Part B: feed-forward`,
      title: "512 feature detectors switch on or stay quiet",
      plain: `Next, each token's vector goes through a small two-step network on its own, with no looking at other tokens. First it is widened to 512 "features". Each feature is a learned pattern detector that lights up (orange) when it recognizes something. In this layer, ${Math.round(layer.ffn_active_frac * 100)}% of the 512 features are clearly active for <LINE>. Then the 512 numbers are squeezed back down to 128.`,
      numbers: `hidden = GELU(up · RMSNorm(x)) is 512 values; out = down · hidden is 128 values. GELU lets positive signals through and mostly blocks negative ones.`,
      render(v) {
        const hidden = layer.ffn_hidden_last;
        const grid = [];
        for (let r = 0; r < 16; r++) grid.push(hidden.slice(r * 32, r * 32 + 32));
        const f = el("div", "wt-figure");
        f.append(el("div", "wt-fig-cap", "The 512 features for <LINE>, as a 16 × 32 grid"), matrixCanvas(grid, null, "auto"), legend());
        v.append(f);
        const s = robustScale(layer.ffn_out_last.concat(layer.attn_out_last));
        v.append(el("div", "wt-fig-cap", "What each part adds to <LINE>'s vector in this layer (128 numbers each)"));
        v.append(labeledStrip("attention adds", layer.attn_out_last, s));
        v.append(labeledStrip("feed-fwd adds", layer.ffn_out_last, s));
      },
    });

    const prev = li > 0 ? T.trace.layers[li - 1].lens_top5[0] : null;
    const guess = layer.lens_top5[0];
    let story;
    if (!prev) story = `After one layer, the closest guess is "${guess.token}" (${pct(guess.p)}). The model has barely started thinking.`;
    else if (prev.token === guess.token) story = `The guess stays "${guess.token}", now at ${pct(guess.p)}.`;
    else story = `The guess changes from "${prev.token}" to "${guess.token}" (${pct(guess.p)}).`;
    if (n === cfg.layers) story += " This is the real answer: the model's final belief.";

    steps.push({
      chapter: `L${n}`, stage: n,
      kicker: `Layer ${n} of ${cfg.layers} · Part C: update and peek`,
      title: n === cfg.layers ? "The final vector and the final guess" : "If we stopped here, what would it guess?",
      plain: `Each layer doesn't replace the vector. It adds to it. This running total is called the residual stream. We can "peek" at any layer by sending the current vector straight to the output step, a trick called the logit lens. ${story}`,
      numbers: `x ← x + attention(x), then x ← x + feedforward(x). Length of <LINE>'s vector: ${layer.norm_out_by_pos[last]}. Peek = softmax(word_table · RMSNorm(x)).`,
      render(v) {
        const s = robustScale(layer.x_in_last.concat(layer.x_out_last));
        v.append(labeledStrip("before layer", layer.x_in_last, s), labeledStrip("after layer", layer.x_out_last, s), legend());
        const f = el("div", "wt-figure");
        f.append(el("div", "wt-fig-cap", `Peek after layer ${n}: top 5 next-token guesses`), bars(layer.lens_top5, { highlight: (it, i) => it === layer.lens_top5[0] }));
        v.append(f);
        const trail = el("div", "wt-trail");
        T.trace.layers.slice(0, n).forEach((l, i) => {
          const c = el("span", "wt-trail-chip" + (i === li ? " is-on" : ""), `L${i + 1}: ${l.lens_top5[0].token}`);
          trail.append(c);
        });
        v.append(el("div", "wt-fig-cap", "How the guess has evolved so far"), trail);
      },
    });
  });

  // 4. Output head
  const P = T.prediction;
  steps.push({
    chapter: "Predict", stage: cfg.layers,
    kicker: "Step 4 · Score every word",
    title: `128 numbers become ${cfg.vocab} scores`,
    plain: `The final vector is normalized, then compared with every row of the same word table from step 2. A word whose row "points the same way" as the vector gets a high score. Softmax turns the ${cfg.vocab} scores into probabilities that add up to 100%. Here the model is almost certain: "${P.raw_top15[0].token}" gets ${pct(P.raw_top15[0].p)}. That makes sense, because every training story opens with "The ...".`,
    numbers: `scores = word_table (${cfg.vocab}×${cfg.d_model}) · RMSNorm(x) · scores range ${P.logit_min} to ${P.logit_max} · p = softmax(scores).`,
    render(v) {
      v.append(el("div", "wt-fig-cap", "Top 15 of 752 tokens (raw probabilities)"), bars(P.raw_top15, { highlight: (it) => it === P.raw_top15[0], showLogit: true }));
    },
  });

  // 5. Sampling
  const chosen = T.generation[0];
  steps.push({
    chapter: "Sample", stage: cfg.layers,
    kicker: "Step 5 · Pick one token",
    title: "Roll weighted dice, with safety rules",
    plain: `The model gives probabilities, but something still has to choose. The runtime applies three rules. Temperature ${T.sampling.temperature} sharpens the odds. <EOS> is blocked so a story can't stop mid-line. Only the top ${T.sampling.top_k} candidates stay in the running. Then it rolls weighted dice. With "${P.filtered_top15[0].token}" at ${pct(P.filtered_top15[0].p)}, the dice almost always land on it, and they did: "${chosen.chosen}".`,
    numbers: `seed ${T.sampling.seed} · after the top-k filter ${P.kept} tokens are still possible · chosen "${chosen.chosen}" with p = ${pct(chosen.p_chosen)}.`,
    render(v) {
      const cols = el("div", "wt-sample-cols");
      const col = (title, items) => {
        const c = el("div", "wt-sample-col");
        c.append(el("div", "wt-fig-cap", title), bars(items.slice(0, 6), { highlight: (it) => it.token === chosen.chosen }));
        return c;
      };
      cols.append(col("1 · raw", P.raw_top15), col(`2 · temperature ${T.sampling.temperature}`, P.temp_top15), col(`3 · <EOS> blocked, top-${T.sampling.top_k}`, P.filtered_top15));
      const pick = el("div", "wt-picked");
      pick.append(el("span", "", "Chosen next token:"), el("strong", "", chosen.chosen));
      v.append(cols, pick);
    },
  });

  // 6. Loop
  steps.push({
    chapter: "Loop", stage: null,
    kicker: "Step 6 · Repeat",
    title: "Add the token, run everything again",
    plain: `The chosen token is added to the end of the prompt, and steps 2 to 5 run again to get the next token, then again, until <END>. The KV cache means earlier tokens aren't recomputed. Notice how sure the model is almost every time. The highlighted word is where it made a real choice: which cosy prop Bluey finds. That is where variety comes from: each seed rolls the dice differently at moments like this.`,
    numbers: `Click any token to see what else it considered. Full stories are about 270 tokens; this shows the first line (${T.generation.length} tokens).`,
    render(v) {
      const line = el("div", "wt-gen");
      const info = el("div", "wt-gen-info");
      info.append(el("div", "wt-small", "Click a token to see the alternatives."));
      const showInfo = (s) => {
        info.replaceChildren(el("div", "wt-fig-cap", `Step with ${s.context_len} tokens of context → chose "${s.chosen}" (${pct(s.p_chosen)} after sampling rules)`),
          bars(s.top5, { highlight: (it) => it.token === s.chosen }));
      };
      const chips = T.generation.map((s) => {
        const c = el("button", "wt-gen-tok" + (s.p_chosen < 0.9 ? " is-choice" : ""), s.chosen);
        c.type = "button";
        c.title = `p = ${pct(s.p_chosen)}`;
        c.addEventListener("click", () => {
          chips.forEach((x) => x.classList.remove("is-on"));
          c.classList.add("is-on");
          showInfo(s);
        });
        return c;
      });
      const promptChip = el("span", "wt-gen-prompt", toks.join(" "));
      line.append(promptChip);
      v.append(line, info);
      if (reduceMotion) { chips.forEach((c) => line.append(c)); return; }
      let i = 0;
      const tick = () => {
        if (!line.isConnected || i >= chips.length) return;
        chips[i].classList.add("is-new");
        line.append(chips[i++]);
        setTimeout(tick, 550);
      };
      tick();
    },
  });

  function attnGrid(matrix) {
    const t = matrix.length;
    const g = el("div", "wt-attn-grid");
    g.style.gridTemplateColumns = `90px repeat(${t}, 1fr)`;
    g.append(el("span", ""));
    toks.forEach((tk) => g.append(el("span", "wt-attn-h", tk.replace(/^<|>$/g, ""))));
    matrix.forEach((row, i) => {
      g.append(el("span", "wt-attn-h wt-attn-r", toks[i].replace(/^<|>$/g, "")));
      row.forEach((p, j) => {
        const c = el("span", "wt-attn-cell" + (j > i ? " is-masked" : ""), j > i ? "" : Math.round(p * 100));
        if (j <= i) c.style.background = `rgba(251,146,60,${0.08 + p * 0.85})`;
        g.append(c);
      });
    });
    return g;
  }

  // ---------- rail, controls ----------
  const rail = $("wt-rail");
  const chapters = [...new Set(steps.map((s) => s.chapter))];
  chapters.forEach((ch) => {
    const b = el("button", "wt-rail-btn", ch);
    b.type = "button";
    b.addEventListener("click", () => go(steps.findIndex((s) => s.chapter === ch)));
    rail.append(b);
  });

  let cur = 0;
  let timer = null;
  function go(i) {
    cur = Math.max(0, Math.min(steps.length - 1, i));
    const s = steps[cur];
    $("wt-kicker").textContent = s.kicker;
    $("wt-title").textContent = s.title;
    $("wt-plain").textContent = s.plain;
    $("wt-numbers").textContent = s.numbers;
    const v = $("wt-visual");
    v.replaceChildren();
    s.render(v);
    $("wt-count").textContent = `${cur + 1} / ${steps.length}`;
    $("wt-progress").style.width = ((cur + 1) / steps.length) * 100 + "%";
    $("wt-prev").disabled = cur === 0;
    $("wt-next").disabled = cur === steps.length - 1;
    [...rail.children].forEach((b) => b.classList.toggle("is-on", b.textContent === s.chapter));
    highlightMap(s.stage);
    const panel = $("wt-panel");
    panel.classList.remove("is-enter");
    void panel.offsetWidth;
    panel.classList.add("is-enter");
    if (cur === steps.length - 1) stop();
  }
  function stop() {
    clearTimeout(timer); timer = null;
    $("wt-play").textContent = "▶ Play";
    $("wt-play").setAttribute("aria-pressed", "false");
  }
  function play() {
    if (cur === steps.length - 1) go(0);
    $("wt-play").textContent = "❚❚ Pause";
    $("wt-play").setAttribute("aria-pressed", "true");
    const tick = () => {
      timer = setTimeout(() => {
        if (cur < steps.length - 1) { go(cur + 1); tick(); } else stop();
      }, Number($("wt-speed").value));
    };
    tick();
  }
  $("wt-prev").addEventListener("click", () => { stop(); go(cur - 1); });
  $("wt-next").addEventListener("click", () => { stop(); go(cur + 1); });
  $("wt-play").addEventListener("click", () => (timer ? stop() : play()));
  root.addEventListener("keydown", (e) => {
    if (e.target.tagName === "SELECT") return;
    if (e.key === "ArrowRight") { stop(); go(cur + 1); }
    if (e.key === "ArrowLeft") { stop(); go(cur - 1); }
  });
  go(0);
})();
